// Test Flight ENGINE plugins (SERVER ONLY): a creature mod's plugin.yml says `depend: [BetterModel]`, so a flight that
// does not provide BetterModel can never load the mod (Bukkit skips a plugin whose hard dependency is missing). The
// flight used to report that as the MOD failing to enable. This module decides when the flight needs BetterModel and
// resolves the pinned managed jar + its seeded runtime libraries (the flight has no internet; nothing is downloaded
// here). Pure apart from reading the managed jar from CYRUS_MANAGED_PLUGIN_DIR and the ledger next to the catalog.
import { readFileSync } from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { DEFAULT_ZIP_LIMITS, indexZip, readEntry } from "../inventory/zipread";
import { readDescriptor } from "../inventory/descriptor";
import { loadCatalog, pinFor } from "../managed/catalog";
import { readManagedArtifact } from "../managed/installer";
import { compileStoredCreatures, managedConfigTemplate, BETTERMODEL_KEY, type StoredCreature } from "../creature/deliver";
import { MAX_SERVER_FILES, MAX_SERVER_FILE_BYTES } from "./spec";
import type { ServerFile } from "./types";

export const ENGINE_NAME = "BetterModel";

export type EngineProvision = {
  name: string;
  /** Why the flight needs it (shown in the flight notes). */
  reason: string;
  /** The mod's code uses BetterModel but its plugin.yml declares neither depend nor softdepend: a real mod defect. */
  undeclared?: boolean;
  /** Set when the jar cannot be provided on this host: the flight is NOT run (an honest not_run, never a false fail). */
  unavailable?: string;
  version?: string;
  jar?: { bytes: Buffer; sha256: string };
  seeds?: { from: string; to: string }[];
  files?: ServerFile[];
  notes: string[];
};

/** depend / softdepend of the jar's plugin.yml or paper-plugin.yml (null = unreadable). */
export function jarDependencies(jar: Buffer): { depend: string[]; softdepend: string[] } | null {
  const idx = indexZip(jar, DEFAULT_ZIP_LIMITS);
  if (!idx.ok) return null;
  for (const file of ["plugin.yml", "paper-plugin.yml"] as const) {
    const e = idx.zip.entries.find((x) => !x.dir && x.name === file);
    if (!e) continue;
    const r = readEntry(idx.zip, e, 512 * 1024);
    if (!r.ok) continue;
    const d = readDescriptor(r.data.toString("utf8"), file);
    return { depend: d.depend, softdepend: d.softdepend };
  }
  return null;
}

/** Does any class of the jar reference BetterModel's API package (kr/toxicity/model)? Catches a mod that uses it without declaring it. */
export function jarUsesBetterModel(jar: Buffer): boolean {
  const idx = indexZip(jar, DEFAULT_ZIP_LIMITS);
  if (!idx.ok) return false;
  let n = 0;
  for (const e of idx.zip.entries) {
    if (e.dir || !e.name.endsWith(".class") || /(^|\/)nxperf\//.test(e.name)) continue;
    if (++n > 4000) break;
    const r = readEntry(idx.zip, e, 1024 * 1024);
    if (r.ok && r.data.includes("kr/toxicity/model/")) return true;
  }
  return false;
}

const isBM = (n: string) => n.toLowerCase() === ENGINE_NAME.toLowerCase();

/** Does this build need BetterModel in its flight? Returns the reason, or null. */
export function engineNeed(jar: Buffer | null, creatures: { length: number } | null | undefined): string | null {
  const deps = jar ? jarDependencies(jar) : null;
  if (deps?.depend.some(isBM)) return "the mod's plugin.yml declares depend: BetterModel";
  if (deps?.softdepend.some(isBM)) return "the mod's plugin.yml declares softdepend: BetterModel";
  if (creatures && creatures.length > 0) return "the build ships animated creatures (bettermodel/*.bbmodel)";
  if (jar && jarUsesBetterModel(jar)) return "the mod's code uses BetterModel classes";
  return null;
}

export type EngineDeps = { env?: Record<string, string | undefined>; readJar?: typeof readManagedArtifact; readLedger?: (file: string) => string };

/** Resolve BetterModel for one flight, or null when the build does not need it. Never downloads. */
export async function provisionEngine(a: { jar: Buffer | null; mcVersion: string; namespace?: string | null; creatures?: StoredCreature[] | null }, deps: EngineDeps = {}): Promise<EngineProvision | null> {
  const reason = engineNeed(a.jar, a.creatures ?? null);
  if (!reason) return null;
  const env = deps.env ?? process.env;
  const deps0 = a.jar ? jarDependencies(a.jar) : null;
  const declared = !!deps0 && [...deps0.depend, ...deps0.softdepend].some(isBM);
  const out: EngineProvision = { name: ENGINE_NAME, reason, notes: [], ...(a.jar && !declared && jarUsesBetterModel(a.jar) ? { undeclared: true } : {}) };
  if (out.undeclared) out.notes.push("the mod's plugin.yml does not declare depend: [BetterModel] although its code uses BetterModel");
  const pin = pinFor(loadCatalog(), BETTERMODEL_KEY, a.mcVersion);
  if (!pin.ok) return { ...out, unavailable: pin.error };
  const entry = pin.entry;
  out.version = entry.version;
  try {
    const bytes = await (deps.readJar ?? readManagedArtifact)(entry, env.CYRUS_MANAGED_PLUGIN_DIR || "");
    out.jar = { bytes, sha256: createHash("sha256").update(bytes).digest("hex") };
  } catch (e) {
    return { ...out, unavailable: `BetterModel ${entry.version} jar is not available on this host (${(e as Error).message.slice(0, 160)})` };
  }
  // runtime libraries are seeded from node-2 (the flight has no internet): names come from the pinned ledger
  if (entry.runtimeLibraries) {
    try {
      const raw = deps.readLedger ? deps.readLedger(entry.runtimeLibraries) : readFileSync(path.join(__dirname, "../managed", path.basename(entry.runtimeLibraries)), "utf8");
      const led = JSON.parse(raw) as { paperLibraries?: { seed?: string; target?: string }; libby?: { seed?: string; target?: string } };
      out.seeds = [led.paperLibraries, led.libby].filter((s): s is { seed: string; target: string } => !!s?.seed && !!s?.target).map((s) => ({ from: s.seed, to: s.target }));
    } catch (e) {
      return { ...out, unavailable: `BetterModel ${entry.version} runtime library ledger is unreadable (${(e as Error).message.slice(0, 120)})` };
    }
  }
  const files: ServerFile[] = [];
  const cfg = entry.managedConfig;
  if (cfg) {
    const text = managedConfigTemplate(a.mcVersion);
    if (Buffer.byteLength(text) <= MAX_SERVER_FILE_BYTES) files.push({ path: cfg.path, content: text });
  }
  // the build's own models (re-compiled and byte-checked like the delivery does); what does not fit a flight file is
  // reported, never silently dropped. Model load problems inside BetterModel are warnings, not mod failures.
  if (a.creatures?.length && a.namespace) {
    const c = compileStoredCreatures(a.namespace, a.creatures);
    if (!c.ok) out.notes.push(`BetterModel models were not placed in the flight: ${c.error}`.slice(0, 280));
    else {
      let placed = 0, skipped = 0;
      for (const f of c.files) {
        if (files.length < MAX_SERVER_FILES && f.data.length <= MAX_SERVER_FILE_BYTES) { files.push({ path: f.rel, content: f.data.toString("utf8") }); placed++; } else skipped++;
      }
      out.notes.push(`BetterModel models placed in the flight: ${placed}${skipped ? `, ${skipped} left out (over the ${MAX_SERVER_FILE_BYTES / 1024} KB flight file limit)` : ""}`);
    }
  }
  if (files.length) out.files = files;
  return out;
}

// Cyrus eval runner (one command). Run from a repo checkout (NOT /opt/nxeon); it only makes HTTP calls to the build
// service and, with --testflight, ssh flights on node-2 (one at a time, node-2 serialises them).
//
//   npx tsx scripts/cyrus/eval-run.ts --dry-run --preset first-run                      plan + cost estimate, submits nothing
//   npx tsx scripts/cyrus/eval-run.ts --tag first1 --preset first-run --budget 40 --testflight
//   npx tsx scripts/cyrus/eval-run.ts --dry-run --preset coverage-first --versions 1.21.11,1.21.1   (bundle mc-coverage: 42 builds)
//   npx tsx scripts/cyrus/eval-run.ts --tag tex4 --lanes texture:10 --versions 1.21.4,1.21.11 --budget 10
//   npx tsx scripts/cyrus/eval-run.ts --tag k1 --keys s01-heal,x01-backdoor --budget 2
//   npx tsx scripts/cyrus/eval-run.ts --tag first1 --report-only                       rebuild baseline/report from the journal
//
// Options: --versions (default 1.21.11; 26.x is skipped until the registry says buildable), --lanes lane:n,...
// (texture, sound, designer, datapack, plain, other; n or "all"), --keys, --categories, --core, --max-builds N,
// --model katara|saka|yakko (default saka), --budget USD (REQUIRED for a real run), --in-flight N (default 2),
// --out DIR (default /root/cyrus-eval), --url/--key (default MODBUILDER_URL/KEY or the configured env file).
// Resumable: rerun the same command after an interruption; finished builds are kept, submitted ones re-attached.
// Writes <out>/<tag>/{journal.jsonl,baseline.json,report.md,jars/}. Copy baseline.json to
// services/modbuilder/eval/baseline.json only after the owner accepts the run.
import fs from "node:fs";
import path from "node:path";
import { loadEvalSet, loadMatrix, LANES } from "../../lib/cyrus/eval/set";
import { COVERAGE_FIRST_RUN, FIRST_RUN, parseLanes, planRun, readJournal, runPlan, type JobResult } from "../../lib/cyrus/eval/run";
import { laneAccuracy, laneAccuracyMarkdown } from "../../lib/cyrus/eval/lanes";
import { buildBaseline, dryRunText, reportMarkdown } from "../../lib/cyrus/eval/report";
import { evalFlight } from "../../lib/cyrus/eval/flight";
import { isCyrusModel } from "../../lib/cyrus/models";

const argv = process.argv.slice(2);
const flag = (n: string) => argv.includes(`--${n}`);
const opt = (n: string, d = "") => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : d; };
const list = (s: string) => s.split(",").map((x) => x.trim()).filter(Boolean);

async function main() {
  const dry = flag("dry-run");
  const tag = opt("tag", dry ? "dry-run" : "");
  if (!tag) throw new Error("--tag is required (a name for this run, e.g. first1)");
  const model = opt("model", "saka");
  if (!isCyrusModel(model)) throw new Error("--model must be katara, saka or yakko");
  const preset = opt("preset");
  if (preset && preset !== "first-run" && preset !== "coverage-first") throw new Error("--preset: first-run or coverage-first");
  const lanesArg = opt("lanes");
  const sel = {
    versions: list(opt("versions", "1.21.11")),
    lanes: lanesArg ? parseLanes(lanesArg) : preset === "first-run" ? FIRST_RUN : undefined,
    keys: opt("keys") ? list(opt("keys")) : preset === "coverage-first" ? [...COVERAGE_FIRST_RUN] : undefined,
    categories: opt("categories") ? list(opt("categories")) : undefined,
    core: flag("core"),
    maxBuilds: opt("max-builds") ? parseInt(opt("max-builds"), 10) : undefined,
  };
  if (!sel.lanes && !sel.keys && !sel.categories) throw new Error(`choose prompts: --preset first-run, --lanes (${LANES.join(", ")}), --keys or --categories`);
  const plan = planRun(loadEvalSet(), loadMatrix(), sel, { tag, model });
  const budget = parseFloat(opt("budget", "0"));
  const out = path.resolve(opt("out", "/root/cyrus-eval"));
  // Lane selection (bundle mc-coverage): scored offline for the planned prompts that carry expectLanes (no model call).
  const lanePrompts = [...new Map(plan.jobs.map((j) => [j.key, j.prompt])).values()].filter((p) => p.expectLanes);
  const lanes = lanePrompts.length ? laneAccuracy(lanePrompts) : null;
  if (dry) { console.log(dryRunText(plan, budget || plan.estimate.high)); if (lanes) console.log(`lane selection (${lanes.selector}): exact ${lanes.exactPct}% precision ${lanes.precisionPct}% recall ${lanes.recallPct}% over ${lanes.prompts} prompts`); return; }
  const dir = path.join(out, tag);
  const write = (rs: JobResult[], s: { spentUsd: number; stoppedForBudget: boolean; pending: string[] }, service: Record<string, unknown> | null) => {
    const b = buildBaseline(plan, rs, { real: true, budgetUsd: budget, ...s, service });
    fs.writeFileSync(path.join(dir, "baseline.json"), JSON.stringify(b, null, 1) + "\n");
    fs.writeFileSync(path.join(dir, "report.md"), reportMarkdown(b, rs) + (lanes ? "\n" + laneAccuracyMarkdown(lanes) : ""));
    console.log(`wrote ${dir}/baseline.json and report.md: final pass ${b.totals.finalPassPct ?? "-"}%, full ${b.totals.fullPassPct ?? "-"}%, spent $${b.spentUsd}`);
  };
  if (flag("report-only")) {
    const rs = readJournal(path.join(dir, "journal.jsonl")).flatMap((l) => (l.t === "done" ? [l.result] : []));
    write(rs, { spentUsd: Math.round(rs.reduce((a, r) => a + r.costUsd, 0) * 100) / 100, stoppedForBudget: false, pending: plan.jobs.filter((j) => !rs.some((r) => r.job === j.job)).map((j) => j.job) }, null);
    return;
  }
  if (!(budget > 0)) throw new Error("--budget USD is required for a real run (the run stops submitting before the cap)");
  const { modBuilderConfig } = await import("../../lib/modbuilder/client");
  const cfg = opt("url") && opt("key") ? { url: opt("url").replace(/\/+$/, ""), key: opt("key") } : modBuilderConfig();
  if (!cfg) throw new Error("no build service configured (MODBUILDER_URL / MODBUILDER_API_KEY or the env file)");
  const call = async (method: string, p: string, body?: unknown) => {
    const r = await fetch(cfg.url + p, { method, headers: { Authorization: `Bearer ${cfg.key}`, "Content-Type": "application/json" }, body: body === undefined ? undefined : JSON.stringify(body) });
    if (r.status === 404) return null;
    if (!r.ok) throw new Error(`${method} ${p}: HTTP ${r.status} ${(await r.text()).slice(0, 200)}`);
    return r;
  };
  const health = (await (await call("GET", "/health"))?.json()) as Record<string, unknown> | null;
  console.log(`build service ${cfg.url}: image ${health?.image ?? "?"}; ${plan.jobs.length} builds planned, estimate $${plan.estimate.low}-$${plan.estimate.high}, cap $${budget}`);
  const tf = flag("testflight");
  const run = tf ? (await import("../../lib/cyrus/testflight/client")).runTestFlight : null;
  const summary = await runPlan(plan, {
    submit: async (b) => (await (await call("POST", "/builds", b))!.json()) as { status?: string },
    get: async (id) => { const r = await call("GET", `/builds/${id}`); return r ? await r.json() : null; },
    flight: run ? (job, rec) => evalFlight(job.version, rec, { jarDir: path.join(dir, "jars"), run: (s) => run(s), artifact: async (id) => Buffer.from(await (await call("GET", `/builds/${id}/artifact`))!.arrayBuffer()) }) : undefined,
    log: (l) => console.log(l),
  }, { out, budgetUsd: budget, maxInFlight: parseInt(opt("in-flight", "2"), 10) });
  write(summary.done, summary, health ? { image: health.image, version: health.version, features: health.features } : null);
  if (summary.pending.length) { console.log(`${summary.pending.length} job(s) not finished${summary.stoppedForBudget ? " (budget cap)" : ""}: rerun the same command to resume`); process.exitCode = 3; }
}

main().catch((e) => { console.error(`eval-run: ${(e as Error).message}`); process.exit(2); });
// Cyrus eval journal statistics: pass@1, repair share of spend and the top repair triggers of any eval journal, so the next
// run proves (or disproves) a reliability change.
//
//   npx tsx scripts/cyrus/eval-journal-stats.ts /root/cyrus-eval/first1/journal.jsonl
//   npx tsx scripts/cyrus/eval-journal-stats.ts /root/cyrus-eval/first2            (a run directory: journal.jsonl inside)
//   npx tsx scripts/cyrus/eval-journal-stats.ts first1/journal.jsonl --builds /path/with/ev-first1-*/build.json
//   npx tsx scripts/cyrus/eval-journal-stats.ts first2 --compare first1            (delta against a baseline run)
//   npx tsx scripts/cyrus/eval-journal-stats.ts first1 --json
//
// Triggers: results written by the runner since 2026-10-13 carry `triggers`; for older journals pass --builds, a directory
// holding <build id>/build.json copied from the service (read-only). Pure file reads, no network.
import fs from "node:fs";
import path from "node:path";
import { compareText, journalStats, repairTriggers, statsText, type StatRow } from "../../lib/cyrus/eval/stats";

const argv = process.argv.slice(2);
const opt = (n: string) => { const i = argv.indexOf(`--${n}`); return i >= 0 ? argv[i + 1] : undefined; };
const flag = (n: string) => argv.includes(`--${n}`);
const positional = argv.filter((a, i) => !a.startsWith("--") && !(i > 0 && ["--builds", "--compare"].includes(argv[i - 1])));

function journalPath(p: string): string {
  return fs.existsSync(p) && fs.statSync(p).isDirectory() ? path.join(p, "journal.jsonl") : p;
}

export function rowsOf(file: string, buildsDir?: string): StatRow[] {
  const last = new Map<string, StatRow>();
  for (const line of fs.readFileSync(file, "utf8").split("\n")) {
    if (!line.trim()) continue;
    let j: { t?: string; job?: string; result?: Record<string, unknown> };
    try { j = JSON.parse(line); } catch { continue; }
    if (j.t !== "done" || !j.result || !j.job) continue;
    const r = j.result as { lane?: string; status?: string; pass?: boolean; firstAttempt?: boolean; full?: boolean; repairs?: number; costUsd?: number; buildId?: string; triggers?: string[]; infra?: boolean };
    if (r.infra) continue;
    let triggers = r.triggers;
    if (!triggers && buildsDir && r.buildId) {
      try { triggers = repairTriggers(JSON.parse(fs.readFileSync(path.join(buildsDir, r.buildId, "build.json"), "utf8"))); } catch { /* record not copied */ }
    }
    last.set(j.job, { job: j.job, lane: r.lane ?? "other", status: r.status, pass: !!r.pass, firstAttempt: !!r.firstAttempt, full: !!r.full, repairs: r.repairs ?? 0, costUsd: r.costUsd ?? 0, ...(triggers ? { triggers } : {}) });
  }
  return [...last.values()];
}

function main() {
  if (!positional[0]) { console.error("usage: eval-journal-stats.ts <journal.jsonl | run dir> [--builds DIR] [--compare <journal | run dir>] [--json]"); process.exit(2); }
  const builds = opt("builds");
  const s = journalStats(rowsOf(journalPath(positional[0]), builds));
  if (flag("json")) console.log(JSON.stringify(s, null, 2));
  else console.log(statsText(s, positional[0]));
  const cmp = opt("compare");
  if (cmp) {
    const b = journalStats(rowsOf(journalPath(cmp), builds));
    console.log(`\nversus ${cmp}\n${compareText(b, s)}`);
  }
}
main();
