                BossDef d = args.length >= 3 ? b.def(args[2].toLowerCase(Locale.ROOT)) : null;
                if (d == null) { say(sender, "Usage: /" + label + " boss spawn <id> [<world> <x> <y> <z> | spawn]", NamedTextColor.RED); return; }
