                    test = true;
                    for (Entity e : i.mob.getNearbyEntities(at.range, at.range, at.range)) if (e instanceof LivingEntity le && !(e instanceof Player) && !b.ours(e) && le.isValid() && !le.isDead() && !(e instanceof org.bukkit.entity.ArmorStand)) ts.add(le);
                    b.order(ts, i.mob.getLocation(), BossDef.Select.NEAREST);
                    if (ts.size() > at.max) ts = new ArrayList<>(ts.subList(0, at.max));
                }
                int n = b.cast(i, at, ts, b.designer().now(), false);
