// Cyrus behaviour oracle (oracle-1): the declarative EXPECTATIONS of one build and the stored functional result.
// Pure + client-safe (types and constants only).
//
// An expectation is one thing the mod should DO, derived deterministically from what the build shipped (plugin.yml,
// config.yml, the designer specs, the data pack specs, the creature rig specs). No model call. Each one carries its own
// probe (RCON console checks and / or one scripted-player scenario) and is judged pass / fail / not_run with evidence;
// `not_testable` = the oracle knows the expectation but has no honest way to try it (the reason says why).
// The JSON shape below is the contract with the eval ("behaviour" stage) and the portal panel: docs/cyrus/14-behaviour-oracle.md.
import type { PlaytestStep } from "../../playtest/plan";
import type { RconCheck } from "../types";

export const ORACLE_VERSION = "oracle-1";
/** Portal switch: the gate flies the oracle's probes in the same Test Flight (default OFF). */
export const ORACLE_FLAG = "CYRUS_TESTFLIGHT_ORACLE";
/** Optional model-authored extra expectations (they are only used when a caller passes them AND this is "1"). Default OFF. */
export const ORACLE_EXTRAS_FLAG = "CYRUS_TESTFLIGHT_ORACLE_EXTRAS";
/** The eval stage name (shared with feature/cyrus-eval-realism: keep it). */
export const ORACLE_STAGE = "behaviour";

export const EXPECTATION_KINDS = [
  "mod_enables", "command_responds", "reload_command", "item_given", "ability_effect", "passive_effect", "menu_opens", "menu_click",
  "quest_progress", "boss_spawns", "creature_spawns", "hud_visible", "config_reload", "recipe_registered", "loot_gives", "advancement_reward", "model_extra",
] as const;
export type ExpectationKind = (typeof EXPECTATION_KINDS)[number];

export type ExpectationSource = { from: "plugin.yml" | "config.yml" | "design" | "datapack" | "rig" | "model"; ref: string };

/**
 * What a probe step is for. setup = arranging the test (a vanilla command; if it fails the expectation is not_run, the
 * mod is not blamed); act = doing the thing the mod reacts to; check = the outcome; cleanup = best effort, never judged.
 * probe = a console step whose reply the EVALUATOR checks (`want` / `wantNot`), so a miss never stops the scenario.
 */
export type Role = "setup" | "act" | "check" | "cleanup" | "probe";
export type ProbeStep = { role: Role; step: PlaytestStep; want?: string[]; wantNot?: string[] };
export type ProbeRcon = { role: Role; check: RconCheck; want?: string[]; wantNot?: string[]; /** a reply must not be empty */ nonEmpty?: boolean };

export type Probe = {
  /** Console checks over RCON (they run before the player joins). */
  rcon?: ProbeRcon[];
  /** One scripted-player scenario; with `attachTo` the steps are appended to that expectation's scenario instead. */
  bot?: { steps: ProbeStep[]; attachTo?: string; op?: boolean };
  /** From the flight's own boot checks (mod_enables). */
  boot?: "plugins_enabled";
};

export type Expectation = {
  /** E1, E2, ... in derivation order (stable for the same build). */
  id: string;
  kind: ExpectationKind;
  /** Plain English for the owner: what the mod should do. */
  title: string;
  source: ExpectationSource;
  origin: "derived" | "model";
  probe: Probe | null;
  /** Set (and probe null) when the oracle knows the expectation but cannot try it honestly. */
  notTestable?: string;
};

export type ExpectationStatus = "pass" | "fail" | "not_run" | "not_testable";

/** Stored per expectation (small). */
export type ExpectationResult = {
  id: string; kind: ExpectationKind; title: string; source: string; origin: "derived" | "model";
  status: ExpectationStatus;
  /** Why it failed / did not run / is not testable (null on a pass). */
  reason: string | null;
  /** At most 3 short evidence lines (console replies, what the test player saw). */
  evidence: string[];
};

/** ModBuild.cyrus.testFlight.functional (documented in docs/cyrus/14-behaviour-oracle.md). */
export type StoredFunctional = {
  schema: 1;
  oracle: string;
  stage: typeof ORACLE_STAGE;
  /** done = the probes were flown and judged; not_run = switched off for this flight, an oracle error, or the flight did not complete. */
  state: "done" | "not_run";
  /** passed: at least one expectation ran and none failed; failed: at least one failed; not_run: none ran. */
  verdict: "passed" | "failed" | "not_run";
  /** passed / (passed + failed); null when none ran. Not-run and not-testable never count either way. */
  score: number | null;
  /** (passed + failed) / total: how much of what the mod should do was actually tried. */
  coverage: number | null;
  counts: { total: number; passed: number; failed: number; notRun: number; notTestable: number };
  /** One owner-facing line, never more than what ran. */
  label: string;
  reason?: string;
  expectations: ExpectationResult[];
  timing?: { budgetSec: number; plannedMs: number; rconChecks: number; scenarios: number };
  at: string;
};

/** What the oracle reads from one build. Everything optional except the identity: missing parts just derive less. */
export type OracleInput = {
  version: string;
  pluginName: string;
  /** The project namespace (nx_xxxxxxxx): designer permission / tag names and data pack resources live in it. */
  namespace?: string | null;
  pluginYml: string | null;
  configYml: string | null;
  /** Designer specs as shipped (item / menu / quest / boss / encounter / hud / motion). */
  designs?: { name: string; spec: unknown }[];
  /** Data packs that are PART OF THIS FLIGHT (a pack not flown yields no expectations). */
  datapacks?: { name: string; spec: unknown }[];
  creatures?: { name: string; key?: string | null }[];
  /** Plugins the flight provides next to the mod (e.g. BetterModel). */
  engines?: string[];
  /** Model-authored extra expectations (validated; used only with ORACLE_EXTRAS_FLAG=1). */
  extra?: unknown[];
};

export const ORACLE_LIMITS = {
  expectations: 40, rconChecks: 24, scenarios: 12, budgetSec: 45, joinSec: 15, commands: 6, abilitiesPerItem: 3, items: 4, menus: 3,
  clicksPerMenu: 2, quests: 3, bosses: 2, recipes: 4, lootTables: 2, advancements: 2, evidence: 3, evidenceChars: 240,
} as const;

